  (* [comment removed for export] *)
  Lemma lb_remove_exact : forall p A n LB,
    List.NoDup (map blk_id LB) -> In (p, A, n) LB ->
    lb_bytes (hs_lb_remove H p LB) = lb_bytes LB - n
    /\ (S (length (hs_lb_remove H p LB)) = length LB)%nat
    /\ (forall b, In b (hs_lb_remove H p LB) <-> (In b LB /\ blk_id b <> p)).
  Proof.
    intros p A n LB. induction LB as [|c LB IH]; intros ND Hin; [destruct Hin|].
    cbn in ND. inversion ND as [|x l NI ND']; subst.
    destruct Hin as [->|Hin].
    - cbn in NI. rewrite (proj1 (hh_lb_remove H HH)) by exact NI. rewrite lb_bytes_cons. cbn [blk_size snd length].
      split; [lia|]. split; [reflexivity|].
      intros b. split.
      + intros Hb. split; [right; exact Hb|]. intros E. apply NI. apply in_map_iff. exists b. split; [exact E| exact Hb].
      + intros [[<-|Hb] NE]; [cbn in NE; congruence| exact Hb].
    - assert (NE : blk_id c <> p).
      { intros E. apply NI. apply in_map_iff. exists (p, A, n). split; [symmetry; exact E| exact Hin]. }
      rewrite (hh_lb_remove_cons_ne H HH) by exact NE. rewrite !lb_bytes_cons. cbn [length].
      destruct (IH ND' Hin) as (B1 & B2 & B3). split; [lia|]. split; [lia|].
      intros b. split.
      + intros [<-|Hb]; [split; [left; reflexivity| exact NE]|]. destruct (proj1 (B3 b) Hb) as [K1 K2]. split; [right; exact K1| exact K2].
      + intros [[<-|Hb] NEb]; [left; reflexivity| right]. apply (proj2 (B3 b)). split; [exact Hb| exact NEb].
  Qed.

  Lemma lb_remove_nodup : forall p A n LB,
    List.NoDup (map blk_id LB) -> In (p, A, n) LB -> List.NoDup (map blk_id (hs_lb_remove H p LB)).
  Proof.
    intros p A n LB. induction LB as [|c LB IH]; intros ND Hin; [destruct Hin|].
    cbn in ND. inversion ND as [|x l NI ND']; subst.
    destruct Hin as [->|Hin].
    - cbn in NI. rewrite (proj1 (hh_lb_remove H HH)) by exact NI. exact ND'.
    - assert (NE : blk_id c <> p).
      { intros E. apply NI. apply in_map_iff. exists (p, A, n). split; [symmetry; exact E| exact Hin]. }
      rewrite (hh_lb_remove_cons_ne H HH) by exact NE. cbn. constructor; [| apply IH; assumption].
      intros K. apply in_map_iff in K. destruct K as (b & Eb & Hb). apply (hh_lb_remove_In H HH) in Hb.
      apply NI. apply in_map_iff. exists b. split; assumption.
  Qed.

  (* [comment removed for export] *)
  Lemma blk_same : forall s LB m b1 b2,
    hs_RHEAP H s LB m -> In b1 LB -> In b2 LB -> blk_addr b1 = blk_addr b2 -> blk_size b1 = blk_size b2 -> 0 < blk_size b1 ->
    b1 = b2.
  Proof.
    intros s LB m b1 b2 HP I1 I2 EA ES POS.
    destruct (bptr_eq_dec (blk_id b1) (blk_id b2)) as [E|NE].
    - eapply nodup_blk_eq; [exact (hh_nodup H HH _ _ _ HP)| exact I1| exact I2| exact E].
    - exfalso. destruct (hh_disj H HH _ _ _ _ _ HP I1 I2 NE); lia.
  Qed.

  Lemma blocks_below_hceil : forall s LB m, hs_RHEAP H s LB m -> forall b, In b LB -> blk_addr b + blk_size b <= hceil.
  Proof. intros s LB m HP b Hb. destruct (hh_blocks H HH _ _ _ b HP Hb) as (_ & _ & _ & K & _). exact K. Qed.
End HH.

