  (* [comment removed for export] *)
  Lemma dl_rem_intro : forall s m LB Fa S L ns ls em,
    FieldsC m Fa S L ns ls em -> FieldsOwn LB em -> hs_RHEAP H s LB m ->
    exists bs, map blk_addr bs = L /\ dl_rem m LB (Fa + 32) bs em /\ List.NoDup (map blk_id bs)
               /\ (forall b, In b bs -> In b LB /\ fowned em b).
  Proof.
    intros s m LB Fa S L ns ls em FC OWN HP.
    pose proof FC as (NC & LC & EC & OK & SO & DL & SL & LE & EOK & HFa & HB & AL).
    pose proof (dl_N _ _ _ DL) as ND0.
    assert (G : forall L2 L1, L = L1 ++ L2 ->
      exists bs, map blk_addr bs = L2 /\ dl_rem m LB (Fa + 32) bs em /\ List.NoDup (map blk_id bs)
                 /\ (forall b, In b bs -> In b LB /\ fowned em b)).
    { induction L2 as [|y L2 IH]; intros L1 EL.
      - exists []. split; [reflexivity|]. split; [intros A b B E; destruct A; discriminate|]. split; [constructor|]. intros b [].
      - destruct (IH (L1 ++ [y]) ltac:(rewrite EL, <- app_assoc; reflexivity)) as (bs' & MAP & REM & ND & SUB).
        assert (INy : y ∈ L). { rewrite EL. rewrite elem_of_app, elem_of_cons. right; left; reflexivity. }
        pose proof (proj1 (LE y) INy) as Ky. destruct (em !! y) as [d|] eqn:Ld; [| exfalso; exact (is_Some_None Ky)].
        destruct (OWN y d Ld) as [p [INp SZ]].
        exists ((p, y, esize d) :: bs'). split; [cbn; rewrite MAP; reflexivity|]. split.
        { intros A b B E. destruct A as [|a A'].
          - cbn in E. injection E as <- <-. cbn [blk_addr blk_size fst snd]. split; [exact INp|].
            destruct (mb_lnode m _ _ _ y DL LC ltac:(rewrite elem_of_cons; right; exact INy)) as (nd & _ & _ & _ & C).
            exists d, (wz (cprev (Fa + 32) L y)). split; [exact Ld|]. split; [reflexivity|]. split; [| exact (EC _ _ Ld)].
            rewrite MAP. replace (cnext (Fa + 32) L y) with (lhead (Fa + 32) L2) in C; [exact C|].
            symmetry. rewrite EL. apply cnext_at. rewrite <- EL. exact (nd_cons_tl _ _ ND0).
          - cbn in E. injection E as Ea E'. exact (REM A' b B E'). }
        split.
        { cbn. constructor; [| exact ND]. intros K. apply in_map_iff in K. destruct K as (b' & Eb' & Hb').
          destruct (SUB b' Hb') as [INb' _].
          assert (Eq : b' = (p, y, esize d)) by (eapply nodup_blk_eq; [exact (hh_nodup H HH _ _ _ HP)| exact INb'| exact INp| exact Eb']).
          subst b'. assert (Iy : In y (map blk_addr bs')) by (apply in_map_iff; exists (p, y, esize d); split; [reflexivity| exact Hb']).
          rewrite MAP in Iy. rewrite EL in ND0.
          pose proof (nd_cons_tl _ _ (nd_cons_tl _ _ ND0)) as NDL. apply list.NoDup_app in NDL. destruct NDL as (_ & _ & NDL).
          apply list.NoDup_cons in NDL. destruct NDL as [NI _]. apply NI. apply list_elem_of_In. exact Iy. }
        intros b [<-|Hb]; [| exact (SUB b Hb)]. split; [exact INp|]. exists d. cbn [blk_addr blk_size fst snd]. split; [exact Ld| reflexivity]. }
    exact (G L [] eq_refl).
  Qed.

  (* [comment removed for export] *)
  Lemma fowned_ids : forall s LB m bs L em,
    hs_RHEAP H s LB m -> (forall b, In b bs -> In b LB /\ fowned em b) -> map blk_addr bs = L ->
    (forall e, e ∈ L <-> is_Some (em !! e)) ->
    forall b', In b' LB -> (In (blk_id b') (map blk_id bs) <-> fowned em b').
  Proof.
    intros s LB m bs L em HP SUB MAP LE b' Hb'. split.
    - intros K. apply in_map_iff in K. destruct K as (b & Eb & Hb). destruct (SUB b Hb) as [INb Fb].
      assert (b' = b) by (eapply nodup_blk_eq; [exact (hh_nodup H HH _ _ _ HP)| exact Hb'| exact INb| symmetry; exact Eb]).
      subst b'. exact Fb.
    - intros (d & Ld & SZ).
      assert (IL : blk_addr b' ∈ L). { apply LE. rewrite Ld. eexists; reflexivity. }
      rewrite <- MAP in IL. apply list_elem_of_In in IL. apply in_map_iff in IL. destruct IL as (b & Eb & Hb).
      destruct (SUB b Hb) as [INb (d2 & Ld2 & SZ2)]. rewrite Eb, Ld in Ld2. injection Ld2 as <-.
      pose proof (esize_ge d).
      assert (b = b') by (eapply (blk_same H HH); [exact HP| exact INb| exact Hb'| exact Eb| lia| lia]).
      subst b. apply in_map. exact Hb.
  Qed.

  (* [comment removed for export] *)
  Definition delete_list_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
      (s : PState) (LB : list block) (lo B : Z) (em : gmap Z elt) (errv : word) (m : mem) (mo : Model) : config -> Prop :=
    fun c => exists t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m' (s' : PState) (LB' : list block),
      cfg_ms c = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
                    F (ret_pc ra) fc None m' (seg_rom rsegs)
      /\ hs_KREL H s' (cfg_model c) /\ hs_MPRES H mo (cfg_model c)
      /\ mem_inv rsegs m' /\ stk rsegs m' lo (bv_unsigned sp)
      /\ rw_cells rsegs m' (errno_addr tp) [C4 errv] /\ hs_rauxv_ok H m' B
      /\ hs_RHEAP H s' LB' m'
      /\ (forall b, In b LB' <-> (In b LB /\ ~ fowned em b))
      /\ lb_bytes LB' <= lb_bytes LB /\ (length LB' <= length LB)%nat
      /\ xpres LB' (bv_unsigned sp) [] m m'.

  Definition delete_list_stmt : Prop :=
    forall (ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
           (F : bvmap 5 word) (fc : bv 32) (m : mem) (mo : Model)
           (s : PState) (LB : list block) (Fa lo B : Z) (S L : list Z) (ns : NS) (ls : LS) (em : gmap Z elt) (errv : word),
      a0 = wz Fa ->
      FieldsC m Fa S L ns ls em -> FieldsOwn LB em ->
      bv_unsigned sp <= Fa ->
      hs_RHEAP H s LB m -> hs_KREL H s mo ->
      hs_rauxv_ok H m B -> bv_unsigned sp <= B ->
      stk rsegs m lo (bv_unsigned sp) -> hceil <= lo -> lo <= bv_unsigned sp - DELETE_LIST_STACK ->
      rw_cells rsegs m (errno_addr tp) [C4 errv] -> mem_inv rsegs m -> tp = wz RATP ->
      hs_SR H (delete_list_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc s LB lo B em errv m mo)
        (mkCfg (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
                   F (wz P_DELETE_LIST) fc None m (seg_rom rsegs)) mo).

