(* [comment removed for export] *)
Definition rs_frame (s2 s1 s0 ra : word) : list cell := [C8 (wz 0); C8 (wz 0); C8 s2; C8 s1; C8 s0; C8 ra].

(* [comment removed for export] *)
Lemma rs_seg_z : forall (ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
    (F : bvmap 5 word) (fc : bv 32) (m : mem) (D ptr lo : Z),
  a1 = wz D -> a2 = wz 0 -> a3 = wz 0 ->
  rw_cells rsegs m D [C8 (wz ptr); C8 (wz 0)] ->
  stk rsegs m lo (bv_unsigned sp) -> lo + 48 <= bv_unsigned sp -> hceil <= lo ->
  bv_unsigned sp <= D -> D + 16 <= 2^64 ->
  mem_inv rsegs m ->
  evt rsegs (fun ms' => exists a1v m',
      ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1v (wz 0) (wz 0) a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
               F (ret_pc ra) fc None m' (seg_rom rsegs)
      /\ munch [(bv_unsigned sp + -48, bv_unsigned sp)]%Z m m' /\ wmono rsegs m m' /\ mem_inv rsegs m'
      /\ stk rsegs m' lo (bv_unsigned sp))
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
