(* [comment removed for export] *)
Lemma bf_seg23 : forall (pcv rax sp gp tp t0 t1 t2 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
    (F : bvmap 5 word) (fc : bv 32) (m : mem) (Fa R : Z),
  (R = BF_RA1 \/ R = BF_RA2) -> (pcv = wz R \/ pcv = ret_pc (wz R)) -> 0 <= Fa -> Fa + 88 <= 2^64 -> mem_inv rsegs m ->
  evt rsegs (fun ms' =>
      ms' = MS (mkR (wz (R + 20)) sp gp tp t0 t1 t2 (wz Fa) s1 (wz Fa) (wz (Fa + (if R =? BF_RA1 then 48 else 64))) (wz 0) (wz 0) a4 a5 a6 a7
